#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int A[2][2] = {{1, 2}, {3, 4}};
    int B[2][2] = {{5, 6}, {7, 8}};
    int C[2][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            C[i][j] = A[i][j] + B[i][j];
        }
    }
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            cout << setw(4) << C[i][j];
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int M[2][3] = {{1, 2, 3}, {4, 5, 6}};
    int T[3][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            T[j][i] = M[i][j];
        }
    }
    cout << "Transpose (3 x 2):" << endl;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 2; j++) {
            cout << setw(3) << T[i][j];
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int A[2][2], B[2][2], sum[2][2], diff[2][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> A[i][j];
        }
    }
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> B[i][j];
        }
    }
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            sum[i][j] = A[i][j] + B[i][j];
            diff[i][j] = A[i][j] - B[i][j];
        }
    }
    cout << "A + B:" << endl;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            cout << setw(4) << sum[i][j];
        }
        cout << endl;
    }
    cout << "A - B:" << endl;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            cout << setw(4) << diff[i][j];
        }
        cout << endl;
    }
    return 0;
}

